#include <Arduino.h>

struct Reading {
  uint32_t timeMs;
  int value;
};

QueueHandle_t readings;

void sensorTask(void*) {
  for (;;) {
    Reading item{millis(), analogRead(A0)};
    if (xQueueSend(readings, &item, pdMS_TO_TICKS(20)) != pdPASS) {
      // Decide whether to count, retry, or discard a full-queue sample.
    }
    vTaskDelay(pdMS_TO_TICKS(500));
  }
}

void setup() {
  Serial.begin(115200);
  readings = xQueueCreate(4, sizeof(Reading));
  if (readings == nullptr) {
    Serial.println("Queue creation failed");
    return;
  }
  if (xTaskCreate(sensorTask, "sensor", 3072, nullptr, 1, nullptr) != pdPASS) {
    Serial.println("Task creation failed");
  }
}

void loop() {
  Reading item;
  if (readings != nullptr &&
      xQueueReceive(readings, &item, pdMS_TO_TICKS(1000)) == pdPASS) {
    Serial.printf("%lu ms: %d\n",
                  static_cast<unsigned long>(item.timeMs), item.value);
  }
}

#include <Arduino.h>
QueueHandle_t samples = nullptr;
void reader(void*) { const int value = 7; for (;;) { if (xQueueSend(samples, &value, pdMS_TO_TICKS(100)) != pdPASS) vTaskDelay(pdMS_TO_TICKS(100)); vTaskDelay(pdMS_TO_TICKS(1000)); } }
void setup() { Serial.begin(115200); samples = xQueueCreate(2, sizeof(int)); if (samples == nullptr || xTaskCreate(reader, "reader", 2048, nullptr, 1, nullptr) != pdPASS) { if (samples) vQueueDelete(samples); samples = nullptr; Serial.println("queue/task setup failed"); } }
void loop() { int value; if (samples && xQueueReceive(samples, &value, pdMS_TO_TICKS(1500)) == pdPASS) Serial.printf("sample=%d\n", value); else vTaskDelay(pdMS_TO_TICKS(100)); }
